import XCTest
import Foundation
@testable import MediaPreservation
final class ManifestPerformanceTests:XCTestCase{
 func testGeneratedMixedManifestPlanning100k()throws{var results:[[String:Any]]=[];let binding=ManifestBinding(accountID:UUID(),deviceID:UUID(),libraryID:UUID());for count in [1000,10000,100000]{let started=Date();var resources=0,wireBytes=0;for i in 0..<count{try autoreleasepool{let types=i%4==0 ? [1]:i%4==1 ? [1,9]:i%4==2 ? [1,5,7]:[1,5,7,8];let source=MediaSourceSnapshot(localID:"generated-\(i)",mediaType:"image",livePhoto:i%4==1,resources:types.enumerated().map{ResourceDescriptor(ordinal:$0.offset,resourceType:$0.element,uti:$0.element==9 ? "com.apple.quicktime-movie":"public.jpeg")}),m=MediaManifest(binding:binding,source:source);resources+=m.resources.count;wireBytes+=try JSONSerialization.data(withJSONObject:m.wireMetadata()).count;XCTAssertTrue(m.source.enumerationValid)}};results.append(["logicalAssets":count,"resources":resources,"manifestAndWirePlanningMs":Date().timeIntervalSince(started)*1000,"serializedBytesProcessed":wireBytes]);XCTAssertEqual(resources,count*5/2)};let data=try JSONSerialization.data(withJSONObject:["scope":"Generated native manifest construction and per-asset wire metadata serialization; one manifest resident at a time. Not durable queue insertion or device capture throughput.","results":results],options:[.prettyPrinted,.sortedKeys]);var project=URL(fileURLWithPath:#filePath);for _ in 0..<7{project=project.deletingLastPathComponent()};let output=project.appendingPathComponent("docs/MEDIA_MANIFEST_NATIVE_PERFORMANCE.json");try data.write(to:output)}
}
